/** Local subtractive rounding of the upper-left carrier-window end. Original
 * moving components, bearings, pivots, material zones and other triangles stay
 * unchanged. SHA guard refers to exact input asset, before derived finishes. */
export function repairCarrierTip(mesh,{verifiedSHA256}={}){
 if(mesh?.userData?.replacementForSourceIndex!==0)return null;
 if(verifiedSHA256!==patch.sourceSHA256)throw Error('Carrier-tip source SHA mismatch');
 const original=mesh.geometry,p=original?.attributes?.position,n=original?.attributes?.normal,u=original?.attributes?.uv,index=original?.index;
 if(!p||!n||!u||!index||p.count!==patch.sourceVertexCount||index.count!==patch.sourceIndexCount||Object.keys(original.attributes).sort().join(',')!=='normal,position,uv')throw Error('Carrier-tip geometry fixture mismatch');
 if([p,n,u].some(a=>a.isInterleavedBufferAttribute||a.normalized))throw Error('Unsupported carrier-tip attributes');
 const copy=original.clone(),removed=new Set(patch.removedTriangles),indices=[];
 for(let i=0;i<index.count;i+=3)if(!removed.has(i/3))indices.push(index.getX(i),index.getX(i+1),index.getX(i+2));
 const rows=patch.replacementRows,attrs=[['position',p,0,3],['normal',n,3,3],['uv',u,6,2]];
 for(const[name,a,start,size]of attrs){const values=new Float32Array(a.array.length+rows.length*size);values.set(a.array);rows.forEach((r,i)=>{for(let k=0;k<size;k++)values[a.array.length+i*size+k]=r[start+k];});copy.setAttribute(name,new BufferAttribute(values,size));}
 rows.forEach((_,i)=>indices.push(p.count+i));copy.setIndex(indices);copy.computeBoundingBox();copy.computeBoundingSphere();
 const audit={revision:CARRIER_TIP_REVISION,sourceSHA256:verifiedSHA256,radiusMM:patch.radiusMM,removedVolumeMM3:patch.removedVolumeMM3,changedOriginalTriangles:patch.removedTriangles.length,replacementTriangles:rows.length/3,scope:'Local rounded window lip; sampled clearance, not manufacturing certification'};
 copy.userData={...original.userData,carrierTip:audit};mesh.geometry=copy;
 let disposed=false;return {audit,dispose(){if(disposed)return;disposed=true;if(mesh.geometry===copy)mesh.geometry=original;copy.dispose();}};
}
